INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", 21, "", 0, "vo_wac_220730", "vo_wac_220730_003", "", 16612, "", 16612040, 0);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 11, 0.5, 1, 105111, "まったくもう……\nみんなして絵の具まみれじゃない。\nって、あら？　この赤いのは……", 1, 16612, 0, 16612041, 10);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", 91, "", "", 0, "", "", 16612, "", 16612042, "");
