INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 11, 0.5, 1, 111011, "ううむ、指定通りに描いてはみたが、\nいかんせん芸術性に欠けるな……\nぼくの個性は不要とのことだが、\n端的に言って弾圧じゃあないか。", 1, 17312, 0, 17312009, 10);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", 91, "", "", 0, "", "", 17312, "", 17312010, "");
