INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 11, 0.5, 1, 103111, "ふぅ、なんとか描き終わりましたね。\n今回は自分の力だけで挑戦したので、\n時間がかかってしまいました。\nでも、良い経験になったと思います。", 1, 27512, 0, 27512009, 10);
