INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 11, 0.5, 1, 107111, "ふーむ……描けば描くほど、\n新しいイメージが湧いてきて困るな☆\n次はもう少し考えてから、\nやってみるか？", 1, 28512, 0, 28512009, 10);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", 91, "", "", 0, "", "", 28512, "", 28512010, "");
