INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 11, 0.5, 1, 110911, "ハ？　先輩、いまなんて言いました？\nこの城壁お絵かきプロジェクトに、\nカルミナちゃんたちも参加してる？\n三人ともうっかり壁にサイン書いてた？", 1, 37712, 0, 37712009, 10);
