INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 11, 0.5, 1, 105111, "ふぅ、これでいいかしら？\n普段もカルテにスケッチを描く機会は\nあるけれど、絵筆を使ってしっかりと\n描くのはなかなか大変ね……", 1, 38612, 0, 38612026, 10);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", 91, "", "", 0, "", "", 38612, "", 38612027, "");
